-- 本地演示数据种子。这不是迁移脚本，刻意不放在 db/migration 下。
--
-- 为什么不走 Flyway：application.yml 里 validate-on-migrate: true 且只有一个 location。
-- 种子一旦记进 flyway_schema_history，之后谁用 prod profile 连同一个库，都会因为
-- 「已应用的迁移在本地解析不到」而启动失败。而演示数据本来也不该出现在生产库里。
--
-- 谁加载它：DemoDataSeeder，只在 local profile 且业务表为空时执行一次。
-- 灌完就不再碰 —— 在界面上删掉的记录不会在下次启动时复活。
--
-- 为什么是 --column-inserts 而不是 pg_dump 默认的 COPY：
-- COPY ... FROM stdin 是 psql 的客户端特性，走 JDBC 执行不了，脚本会在第一张表就停下。
--
-- 为什么要 session_replication_role：pg_dump 按字母序排表，dtl_attendance 排在
-- org_employee 之前，40 个外键里有若干会被违反。replica 模式关掉外键触发器 ——
-- 整份数据是从一个自洽的库里整体导出的，不需要再逐表校验一遍。这需要超级用户，
-- docker-compose.local.yml 建出来的 aiacademy 就是。
--
-- 不含哪些表，以及为什么：
--   dict_item / cfg_*          —— 由 R__ 与 V4_002 等迁移脚本负责，重复灌会撞唯一键
--   sys_login_log / audit_op_log —— 导出者的登录与操作痕迹，不该跟着代码分发
--   import_batch / sys_export_task / sys_job_run_log —— 同上，是运行痕迹不是业务数据
--   snapshot_warning_light     —— 派生数据，由定时任务自己重算
--   sys_attachment*            —— 附件行指向磁盘上的文件，那些文件不在仓库里
--
-- 为什么删掉了 pg_dump 生成的那句 set_config('search_path', '', false)：
-- 第三个参数 false 表示会话级、不是事务级。脚本自己用 public.xxx 全限定名所以照样跑通，
-- 但执行它的那条连接会带着空的 search_path 回到 HikariCP 连接池，之后任何用到非限定
-- 表名的查询都会报「relation does not exist」。实测过一次：DemoDataSeeder 灌完数据后
-- 再数一遍行数就炸了，异常从 ApplicationReadyEvent 冒出去，整个后端启动失败 ——
-- 数据其实已经提交了，坏的只是那句日志。下面 598 条 INSERT 全部是 public. 前缀，
-- 不需要 search_path。dump-demo-data.ps1 会在重新导出时把这一句剥掉。
--
-- 重新生成：scripts/dump-demo-data.ps1
--

SET session_replication_role = replica;
--
-- PostgreSQL database dump
--


-- Dumped from database version 15.18 (Debian 15.18-1.pgdg13+1)
-- Dumped by pg_dump version 15.18 (Debian 15.18-1.pgdg13+1)

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

